    static func palm(_ ctx: C2D, _ bx: Double, _ by: Double, _ H: Double, _ lean: Double, _ c: (Double, Double, Double), _ r: () -> Double, _ scale: Double) -> (Double, Double) {
        let top: (Double, Double) = (bx + lean * H, by - H)
        let cp: (Double, Double) = (bx + lean * H * 0.15, by - H * 0.55)
        let tw: Double = H * 0.028
