            while i <= 24.0 {
                defer { i += 1 }
                let u: Double = i / 24.0
                let p: (Double, Double) = at(u)
                let wd: Double = tw * (1.15 - u * 0.5)
                left.append((p.0 - wd, p.1))
                right.append((p.0 + wd, p.1))
