                ctx.moveTo(p.0 - wd, p.1 + 1.0)
                ctx.lineTo(p.0 + wd, p.1 - 1.0)
                ctx.stroke()
            }
        }
        let fronds: Double = 11.0
        do {
            var i: Double = 0.0
            while i < fronds {
                defer { i += 1 }
                let a: Double = -Double.pi / 2.0 + ((i / (fronds - 1.0)) - 0.5) * Double.pi * 1.9 + (r() - 0.5) * 0.2
                let L: Double = H * (0.32 + r() * 0.14) * (JS.abs(JS.cos(a)) * 0.4 + 0.75)
