                        defer { k += 1 }
                        let u: Double = k / 22.0
                        let px: Double = (1.0 - u) * (1.0 - u) * top.0 + 2.0 * (1.0 - u) * u * mx + u * u * ex
                        let py: Double = (1.0 - u) * (1.0 - u) * top.1 + 2.0 * (1.0 - u) * u * my + u * u * ey
