    static let STONES: [O_w_h] = ([O_w_h(w: 1.0, h: 0.42), O_w_h(w: 0.82, h: 0.36), O_w_h(w: 0.66, h: 0.32), O_w_h(w: 0.5, h: 0.28), O_w_h(w: 0.36, h: 0.25)] as [O_w_h])
    static func stone(_ ctx: C2D, _ cx: Double, _ cy: Double, _ sw: Double, _ sh: Double, _ pal: Pal, _ seed: Double, _ ghost: Bool) {
