            let i = Double(_ii)
            if i != 0 {
                ctx.lineTo(p.0, p.1)
            } else {
                ctx.moveTo(p.0, p.1)
            }
        }
        ctx.closePath()
        ctx.clip()
        let g: C2DGradient = ctx.createRadialGradient(cx - sw * 0.2, cy - sh * 0.35, 0.0, cx - sw * 0.2, cy - sh * 0.35, sw * 0.7)
        g.addColorStop(0.0, css(pal.rockLight, 0.9))
        g.addColorStop(1.0, css(pal.rockLight, 0.0))
        ctx.fillStyle = C2DStyle(g)
        ctx.fillRect(cx - sw, cy - sh, sw * 2.0, sh * 2.0)
