    static func cairnTops(_ L: Layout, _ n: Double) -> [O_cx_cy_w_h] {
        let base: Double = L.rockW * 0.95
        var y: Double = L.ledgeTop + L.rockW * 0.02
        var out: [O_cx_cy_w_h] = ([] as [O_cx_cy_w_h])
        do {
            var i: Double = 0.0
            while i < n {
                defer { i += 1 }
                let s: O_w_h = STONES[Int(i)]
                let sw: Double = base * s.w
                let sh: Double = base * s.h
                out.append(O_cx_cy_w_h(cx: L.rockX + (((JSMath.rem(i, 2.0)) != 0 ? 1.0 : -(1.0))) * base * 0.03 * i, cy: y - sh * 0.45, w: sw, h: sh))
                y -= sh * 0.82
            }
        }
        return out
    }
    static func cairn(_ ctx: C2D, _ L: Layout, _ pal: Pal, _ stones: Double, _ seed: Double) {
        let all: [O_cx_cy_w_h] = cairnTops(L, 5.0)
        let shadowW: Double = (all[0]).w
        ctx.fillStyle = C2DStyle(css(pal.near, 0.45))
        ctx.beginPath()
        ctx.ellipse(L.rockX + shadowW * 0.05, L.ledgeTop + L.rockW * 0.02, shadowW * 0.6, shadowW * 0.05, 0.0, 0.0, Double.pi * 2.0)
        ctx.fill()
        let k: Double = JS.floor(stones)
        let fr: Double = stones - k
        fe9: for (_ii, s) in all.enumerated() {
            let i = Double(_ii)
            if i < k {
                stone(ctx, s.cx, s.cy, s.w, s.h, pal, seed + i * 9.0, false)
            } else if (i == k && fr > 0.001) {
                let e: Double = 1.0 - fr
                stone(ctx, s.cx, s.cy - e * e * L.rockW * 1.6, s.w, s.h, pal, seed + i * 9.0, false)
            } else {
                stone(ctx, s.cx, s.cy, s.w, s.h, pal, seed + i * 9.0, true)
            }
        }
    }
    static func paintLedge(_ c: C2D, _ w: Double, _ h: Double, _ L: Layout, _ pal: Pal, _ r: () -> Double, _ S: RScene, _ noTree: Bool = false) {
        func top(_ x: Double) -> Double {
