    static func pathLayout(_ L: Layout, _ w: Double, _ h: Double) -> Layout {
        return Layout(horizon: L.horizon, peakX: (L.tall ? w * 0.55 : w * 0.7), peakTop: (L.tall ? h * 0.56 : h * 0.1), peakHalf: (L.tall ? w * 0.55 : w * 0.25), ridgeY: (L.tall ? h * 0.78 : h * 0.62), ledgeTop: L.ledgeTop, ledgeX: L.ledgeX, rockX: L.rockX, rockW: L.rockW, treeX: L.treeX, treeH: L.treeH, sunX: L.sunX, tall: L.tall)
