    static func routeOf(_ w: Double, _ h: Double, _ L: Layout, _ Lp: Layout) -> [(Double, Double, Double, Bool)] {
        var out: [(Double, Double, Double, Bool)] = ([] as [(Double, Double, Double, Bool)])
        let startY: Double = h * 1.02
        let footY: Double = Lp.ridgeY + h * 0.02
        let n: Double = 30.0
        do {
            var i: Double = 0.0
            while i <= n {
                defer { i += 1 }
                let u: Double = i / n
                let y: Double = startY + (footY - startY) * JS.pow(u, 0.7)
                let x: Double = ((L.tall ? w * 0.4 : w * 0.62)) + JS.sin(u * Double.pi * 2.2) * w * ((L.tall ? 0.25 : 0.12)) * (1.0 - u * 0.7)
