            }
        }
        let _d10 = out[Int(Double(out.count) - 1.0)]
        let fx: Double = _d10.0
        let fy: Double = _d10.1
        let sx: Double = Lp.peakX
        let sy: Double = Lp.peakTop + h * 0.01
        let m: Double = 7.0
        do {
            var i: Double = 1.0
            while i <= m {
                defer { i += 1 }
                let u: Double = i / m
                out.append((fx + (sx - fx) * u + ((i < m ? (((JSMath.rem(i, 2.0)) != 0 ? 1.0 : -(1.0))) * w * 0.035 * (1.0 - u) : 0.0)), fy + (sy - fy) * u, 1.0, true))
            }
        }
        return out
