        let sky: C2DSurface = PNT.layer("n-sky", key, w, h, { (c: C2D) -> Void in
            skyGrad(c, w, h, wl, pal)
            let r: () -> Double = rng(S.seed + 50.0)
            do {
                var i: Double = 0.0
                while i < 70.0 {
                    defer { i += 1 }
                    c.fillStyle = C2DStyle(css(pal.sun, 0.25 + r() * 0.5))
