                }
            }
        })
        let mtn: C2DSurface = PNT.layer("n-mtn", key, w, h, { (c: C2D) -> Void in
            paintFar(c, w, h, Lw, pal, rng(S.seed + 1.0), S.seed, S, O_back_peak_ridges(ridges: false))
            paintFar(c, w, h, Layout(horizon: Lw.horizon, peakX: Lw.peakX, peakTop: Lw.peakTop, peakHalf: Lw.peakHalf, ridgeY: wl - h * 0.12, ledgeTop: Lw.ledgeTop, ledgeX: Lw.ledgeX, rockX: Lw.rockX, rockW: Lw.rockW, treeX: Lw.treeX, treeH: Lw.treeH, sunX: Lw.sunX, tall: Lw.tall), pal, rng(S.seed + 2.0), S.seed, S, O_back_peak_ridges(back: false, peak: false))
