            _ = shoreline(c, w, h, (L.tall ? h * 0.93 : h * 0.86), pal, rng(S.seed + 9.0), true, (L.tall ? 0.45 : 0.32), S.seed)
            _ = shoreline(c, w, h, (L.tall ? h * 0.95 : h * 0.92), pal, rng(S.seed + 10.0), false, (L.tall ? 0.3 : 0.15), S.seed + 4.0)
