    static func kind_beach(_ PNT: RPainter2, _ ctx: C2D, _ w: Double, _ h: Double, _ L: Layout, _ pal: Pal, _ S: RScene, _ theme: String, _ t: Double, _ key: String) {
        let hz: Double = (L.tall ? h * 0.74 : h * 0.6)
        let back: C2DSurface = PNT.layer("b-back", key, w, h, { (c: C2D) -> Void in
            skyGrad(c, w, hz, hz, pal)
