    static func kind_sunrise(_ PNT: RPainter2, _ ctx: C2D, _ w: Double, _ h: Double, _ L: Layout, _ pal: Pal, _ S: RScene, _ theme: String, _ t: Double, _ key: String) {
        let ct: Double = (L.tall ? h * 0.76 : h * 0.6)
        let sx: Double = (L.tall ? w * 0.5 : w * 0.7)
        let sy: Double = ct - (S.sun + 0.1) * h * ((L.tall ? 0.34 : 0.35))
        let sky: C2DSurface = PNT.layer("s-sky", key, w, h, { (c: C2D) -> Void in
