                    defer { k += 1 }
                    let a: Double = -Double.pi + (k / 13.0) * Double.pi + JS.sin(k * 3.1) * 0.08 + JS.sin(t * 0.15 + k) * 0.01
                    let wd: Double = 0.015 + (JSMath.rem((k * 0.37), 1.0)) * 0.025
                    let g: C2DGradient = ctx.createRadialGradient(sx, sy, 0.0, sx, sy, R2)
                    g.addColorStop(0.0, css(pal.sun, 0.22 * JS.min(1.0, S.sun + 0.3)))
                    g.addColorStop(1.0, css(pal.sun, 0.0))
                    ctx.fillStyle = C2DStyle(g)
                    ctx.beginPath()
                    ctx.moveTo(sx, sy)
                    ctx.lineTo(sx + JS.cos(a - wd) * R2, sy + JS.sin(a - wd) * R2)
                    ctx.lineTo(sx + JS.cos(a + wd) * R2, sy + JS.sin(a + wd) * R2)
