            let Lp: Layout = Layout(horizon: ct + h * 0.02, peakX: (L.tall ? w * 0.3 : w * 0.52), peakTop: (L.tall ? h * 0.6 : h * 0.18), peakHalf: (L.tall ? w * 0.5 : w * 0.22), ridgeY: L.ridgeY, ledgeTop: L.ledgeTop, ledgeX: L.ledgeX, rockX: L.rockX, rockW: L.rockW, treeX: L.treeX, treeH: L.treeH, sunX: L.sunX, tall: L.tall)
            paintFar(c, w, h, Lp, pal, rng(S.seed + 1.0), S.seed, S, O_back_peak_ridges(back: false, ridges: false))
            let Lq: Layout = Layout(horizon: Lp.horizon, peakX: (L.tall ? w * 0.85 : w * 0.88), peakTop: (L.tall ? h * 0.68 : h * 0.36), peakHalf: (L.tall ? w * 0.3 : w * 0.14), ridgeY: Lp.ridgeY, ledgeTop: Lp.ledgeTop, ledgeX: Lp.ledgeX, rockX: Lp.rockX, rockW: Lp.rockW, treeX: Lp.treeX, treeH: Lp.treeH, sunX: Lp.sunX, tall: Lp.tall)
            paintFar(c, w, h, Lq, pal, rng(S.seed + 5.0), S.seed + 2.0, S, O_back_peak_ridges(back: false, ridges: false))
        })
        ctx.drawImage(peaks, 0.0, 0.0)
