            let r: () -> Double = rng(S.seed + 7.0)
            let W2: Double = w * 2.0
            c.fillStyle = C2DStyle(css(pal.mist))
            c.fillRect(0.0, ct + h * 0.06, W2, h)
            do {
                var row: Double = 0.0
                while row < 6.0 {
                    defer { row += 1 }
                    let y0: Double = ct - h * 0.01 + row * h * 0.035
                    do {
                        var i: Double = 0.0
                        while i < 110.0 {
                            defer { i += 1 }
                            let x: Double = r() * W2
                            let y: Double = y0 + (r() - 0.5) * h * 0.02
                            let rad: Double = h * (0.025 + r() * 0.04) * (1.0 + row * 0.25)
                            c.save()
                            c.translate(x, y)
                            c.scale(1.9, 0.75)
                            let g: C2DGradient = c.createRadialGradient(-rad * 0.2, -rad * 0.35, 0.0, 0.0, 0.0, rad)
                            g.addColorStop(0.0, css(pal.mist, 0.95))
                            g.addColorStop(0.6, css(mixc(pal.mist, pal.far, 0.12), 0.8))
