    static func kind_path(_ PNT: RPainter2, _ ctx: C2D, _ w: Double, _ h: Double, _ L: Layout, _ pal: Pal, _ S: RScene, _ theme: String, _ t: Double, _ key: String) {
        let Lp: Layout = pathLayout(L, w, h)
        let base: C2DSurface = PNT.layer("p-base", key, w, h, { (c: C2D) -> Void in
            skyGrad(c, w, h, Lp.horizon, pal)
            clouds(c, w, h, Lp.horizon, pal, rng(S.seed), 5.0)
            paintFar(c, w, h, Lp, pal, rng(S.seed + 1.0), S.seed, S)
            func hy(_ x: Double) -> Double {
                return ((L.tall ? h * 0.86 : h * 0.8)) - JS.pow(fbm1(x / (w * 0.3) + S.seed, 4.0), 1.4) * h * 0.12
            }
            let hp: [(Double, Double)] = ridgePts(-(0.02) * w, 1.02 * w, 80.0, { _a0, _a1 in hy(_a0) })
            wash(c, (Array(hp) + ([(1.02 * w, h), (-(0.02) * w, h)] as [(Double, Double)])), mixc(pal.mid2, pal.near, 0.55), rng(S.seed + 3.0), O_body_layers_a_v_edge(body: 0.95, layers: 6.0, a: 0.06, v: 0.003, edge: 0.15))
            trees(c, w, hy, h * 0.06, mixc(pal.mid2, pal.near, 0.55), rng(S.seed + 4.0), 1.2)
            granulate(c, w, h, 0.15)
        })
        ctx.drawImage(base, 0.0, 0.0)
        let route: [(Double, Double, Double, Bool)] = routeOf(w, h, L, Lp)
        ctx.save()
        ctx.lineCap = "round"
        ctx.lineJoin = "round"
        do {
            var i: Double = 0.0
            while i < Double(route.count) - 1.0 {
                defer { i += 1 }
                let _d11 = route[Int(i)]
                let x0: Double = _d11.0
                let y0: Double = _d11.1
                let wd0: Double = _d11.2
                let onM: Bool = _d11.3
                let _d12 = route[Int(i + 1.0)]
                let x1: Double = _d12.0
                let y1: Double = _d12.1
                if onM {
                    continue
                }
                ctx.strokeStyle = C2DStyle(css(mixc(pal.rockLight, pal.mid, 0.35), 0.85))
                ctx.lineWidth = wd0
                ctx.beginPath()
                ctx.moveTo(x0, y0)
                ctx.lineTo(x1, y1)
                ctx.stroke()
            }
        }
        ctx.setLineDash(([w * 0.006, w * 0.008] as [Double]))
        ctx.strokeStyle = C2DStyle(css(pal.near, 0.6))
        ctx.lineWidth = JS.max(1.0, w * 0.0025)
        ctx.beginPath()
        var started: Bool = false
        for _e13 in route {
            let x: Double = _e13.0
            let y: Double = _e13.1
            let onM: Bool = _e13.3
            if !onM {
                continue
            }
            if !started {
                ctx.moveTo(x, y)
                started = true
            } else {
                ctx.lineTo(x, y)
            }
        }
        ctx.stroke()
        ctx.setLineDash(([] as [Double]))
        ctx.restore()
        if (S.noYou ?? false) {
            return
        }
        let u: Double = JS.max(0.0, JS.min(1.0, (S.trail ?? 0.0)))
        let k: Double = u * (Double(route.count) - 1.0)
        let i0: Double = JS.floor(k)
        let f: Double = k - i0
        let a: (Double, Double, Double, Bool) = route[Int(i0)]
        let b: (Double, Double, Double, Bool) = route[Int(JS.min(Double(route.count) - 1.0, i0 + 1.0))]
        let px: Double = a.0 + (b.0 - a.0) * f
        let py: Double = a.1 + (b.1 - a.1) * f
        let rad: Double = JS.min(w, h) * 0.012
        let g: C2DGradient = ctx.createRadialGradient(px, py, 0.0, px, py, rad * 5.0)
        g.addColorStop(0.0, "rgba(232,93,78,\(JS.toFixed((0.55 + 0.25 * JS.sin(t * 4.0)), 3.0)))")
        g.addColorStop(1.0, "rgba(232,93,78,0)")
        ctx.fillStyle = C2DStyle(g)
        ctx.beginPath()
        ctx.arc(px, py, rad * 5.0, 0.0, Double.pi * 2.0)
        ctx.fill()
        ctx.fillStyle = "#E85D4E"
        ctx.beginPath()
        ctx.arc(px, py, rad, 0.0, Double.pi * 2.0)
        ctx.fill()
        let top: (Double, Double, Double, Bool) = route[Int(Double(route.count) - 1.0)]
        ctx.strokeStyle = C2DStyle(css(pal.near, 0.8))
        ctx.lineWidth = JS.max(1.0, w * 0.002)
        ctx.beginPath()
        ctx.arc(top.0, top.1, rad * 1.2, 0.0, Double.pi * 2.0)
        ctx.stroke()
    }
    static func kind_fog(_ PNT: RPainter2, _ ctx: C2D, _ w: Double, _ h: Double, _ L: Layout, _ pal: Pal, _ S: RScene, _ theme: String, _ t: Double, _ key: String) {
        let base: C2DSurface = PNT.layer("f-base", key, w, h, { (c: C2D) -> Void in
            skyGrad(c, w, h, h, Pal(paper: pal.paper, sky0: mixc(pal.sky0, pal.mist, 0.3), sky1: pal.mist, far: pal.far, farShade: pal.farShade, snow: pal.snow, mid: pal.mid, mid2: pal.mid2, near: pal.near, rock: pal.rock, rockLight: pal.rockLight, rockDark: pal.rockDark, mist: pal.mist, crack: pal.crack, sun: pal.sun))
            let rows: Double = 4.0
            do {
                var row: Double = 0.0
                while row < rows {
                    defer { row += 1 }
                    let u: Double = row / (rows - 1.0)
                    let col: (Double, Double, Double) = mixc(pal.mist, pal.near, 0.18 + u * u * 0.8)
                    let gy: Double = h * ((L.tall ? 0.8 + u * 0.14 : 0.62 + u * 0.3))
                    let r: () -> Double = rng(S.seed + row * 13.0)
                    let tH: Double = h * ((L.tall ? 0.07 + u * 0.12 : 0.16 + u * 0.38))
                    c.fillStyle = C2DStyle(css(col))
                    c.fillRect(0.0, gy, w, h - gy)
                    do {
                        var x: Double = -(0.05) * w
                        while x < 1.05 * w {
                            defer { x += tH * (0.18 + r() * 0.3) }
                            if fbm1(x / (w * 0.08) + row * 5.0, 3.0) < 0.38 {
                                continue
                            }
                            spruce(c, x, gy + tH * 0.04, tH * (0.6 + r() * 0.6), col, r)
                        }
                    }
                    let g: C2DGradient = c.createLinearGradient(0.0, gy - tH * 0.3, 0.0, gy + h * 0.05)
                    g.addColorStop(0.0, css(pal.mist, 0.0))
                    g.addColorStop(1.0, css(pal.mist, 0.85))
                    c.fillStyle = C2DStyle(g)
                    c.fillRect(0.0, gy - tH * 0.3, w, tH * 0.3 + h * 0.08)
                }
            }
            granulate(c, w, h, 0.12)
        })
        ctx.drawImage(base, 0.0, 0.0)
        let mist: C2DSurface = PNT.layer("f-mist", "\(JS.str(w))x\(JS.str(h)):\(theme):\(JS.str(S.night))", w * 2.0, h, { (c: C2D) -> Void in
            paintMist(c, w * 2.0, h, ([h * 0.55, h * 0.75, h * 0.92] as [Double]), pal, rng(9.0))
        })
        let off: Double = -(JSMath.rem((t * w * 0.01), w))
        ctx.globalAlpha = JS.min(1.0, S.mist * 0.22)
        ctx.drawImage(mist, off, 0.0)
        ctx.globalAlpha = 1.0
    }
    static func kind_lake(_ PNT: RPainter2, _ ctx: C2D, _ w: Double, _ h: Double, _ L: Layout, _ pal: Pal, _ S: RScene, _ theme: String, _ t: Double, _ key: String) {
        let wl: Double = (L.tall ? h * 0.8 : h * 0.64)
        let Lw: Layout = Layout(horizon: wl - h * 0.01, peakX: L.peakX, peakTop: (L.tall ? h * 0.6 : h * 0.12), peakHalf: L.peakHalf, ridgeY: wl - h * 0.1, ledgeTop: L.ledgeTop, ledgeX: L.ledgeX, rockX: L.rockX, rockW: L.rockW, treeX: L.treeX, treeH: L.treeH, sunX: L.sunX, tall: L.tall)
