            ctx.lineWidth = JS.max(1.0, w / 900.0)
            do {
                var k: Double = 1.0
                while k <= 4.0 {
                    defer { k += 1 }
                    ctx.beginPath()
                    ctx.moveTo(bx - bw * 0.5 - k * bw * 0.25, by + k * bw * 0.02)
