            do {
                var i: Double = 0.0
                while i < 70.0 {
                    defer { i += 1 }
                    let side: Double = (i < 40.0 ? 1.0 : 0.0)
                    let x: Double = (side != 0 ? w * (0.82 + r() * 0.2) : w * ((L.tall ? r() * 0.25 : 0.45 + r() * 0.12)))
                    let y: Double = h * (0.97 + r() * 0.05)
                    let ht: Double = h * ((L.tall ? 0.05 + r() * 0.08 : 0.1 + r() * 0.18))
                    c.lineWidth = JS.max(1.0, (w / 1000.0) * (1.0 + r() * 1.5))
                    c.beginPath()
                    c.moveTo(x, y)
                    c.quadraticCurveTo(x + (r() - 0.3) * ht * 0.2, y - ht * 0.6, x + (r() - 0.2) * ht * 0.35, y - ht)
                    c.stroke()
                    if r() < 0.2 {
                        c.fillStyle = C2DStyle(css(pal.near))
                        c.beginPath()
                        c.ellipse(x + (r() - 0.2) * ht * 0.3, y - ht * 0.85, JS.max(1.5, w * 0.003), ht * 0.08, 0.1, 0.0, Double.pi * 2.0)
                        c.fill()
                    }
                }
            }
        })
        ctx.drawImage(reeds, 0.0, 0.0)
    }
    static func kind_sunset(_ PNT: RPainter2, _ ctx: C2D, _ w: Double, _ h: Double, _ L: Layout, _ pal: Pal, _ S: RScene, _ theme: String, _ t: Double, _ key: String) {
        let hz: Double = (L.tall ? h * 0.76 : h * 0.62)
        let sx: Double = (L.tall ? w * 0.42 : w * 0.66)
        let sy: Double = hz - (S.sun + 0.05) * h * ((L.tall ? 0.2 : 0.4))
        let sky: C2DSurface = PNT.layer("ss-sky", key, w, h, { (c: C2D) -> Void in
            skyGrad(c, w, h, hz, pal)
            clouds(c, w, h, hz, pal, rng(S.seed), 7.0)
        })
        ctx.drawImage(sky, 0.0, 0.0)
        ctx.save()
        ctx.beginPath()
        ctx.rect(0.0, 0.0, w, hz)
        ctx.clip()
        sunDisc(ctx, sx, sy, JS.min(w, h) * ((L.tall ? 0.06 : 0.085)), pal, 1.0)
        ctx.restore()
        let sea: C2DSurface = PNT.layer("ss-sea", key, w, h, { (c: C2D) -> Void in
            let g: C2DGradient = c.createLinearGradient(0.0, hz, 0.0, h)
            g.addColorStop(0.0, css(mixc(pal.mid, pal.sky1, 0.3)))
            g.addColorStop(1.0, css(mixc(pal.mid2, pal.near, 0.3)))
            c.fillStyle = C2DStyle(g)
            c.fillRect(0.0, hz, w, h - hz)
            let r: () -> Double = rng(S.seed + 2.0)
            c.strokeStyle = C2DStyle(css(pal.mid2, 0.4))
            c.lineWidth = JS.max(1.0, w / 900.0)
            do {
                var i: Double = 0.0
                while i < 90.0 {
                    defer { i += 1 }
                    let y: Double = hz + JS.pow(r(), 1.5) * (h - hz)
                    let x: Double = r() * w
                    let l: Double = w * (0.015 + r() * 0.05) * (1.0 + (y - hz) / (h * 0.25))
                    c.beginPath()
                    c.moveTo(x, y)
                    c.quadraticCurveTo(x + l / 2.0, y + h * 0.003, x + l, y)
                    c.stroke()
                }
            }
        })
        ctx.drawImage(sea, 0.0, 0.0)
        glitter(ctx, sx, hz, h, w, t, pal, 1.0)
        let rocks: C2DSurface = PNT.layer("ss-rocks", key, w, h, { (c: C2D) -> Void in
            let r: () -> Double = rng(S.seed + 3.0)
            func blob(_ x: Double, _ y: Double, _ rw: Double, _ rh: Double) {
                var pts: [(Double, Double)] = ([] as [(Double, Double)])
                do {
                    var k: Double = 0.0
                    while k <= 16.0 {
                        defer { k += 1 }
                        let a: Double = Double.pi + (k / 16.0) * Double.pi
                        pts.append((x + JS.cos(a) * rw * (0.85 + fbm1(k * 0.5 + x, 3.0) * 0.3), y + JS.sin(a) * rh * (0.75 + fbm1(k * 0.7 + y, 3.0) * 0.4)))
                    }
                }
                wash(c, deform((Array(pts) + ([(x + rw, y + rh * 0.4), (x - rw, y + rh * 0.4)] as [(Double, Double)])), 3.0, 0.06, r), pal.near, r, O_body_layers_a_v_edge(body: 0.97, layers: 4.0, a: 0.07, v: 0.01, edge: 0.2))
            }
            let by: Double = (L.tall ? h * 0.95 : h * 0.9)
            blob(w * ((L.tall ? 0.82 : 0.86)), by, w * ((L.tall ? 0.22 : 0.12)), h * ((L.tall ? 0.07 : 0.17)))
            blob(w * ((L.tall ? 0.6 : 0.74)), by + h * 0.02, w * ((L.tall ? 0.1 : 0.05)), h * ((L.tall ? 0.035 : 0.08)))
            blob(w * ((L.tall ? 0.1 : 0.55)), by + h * 0.03, w * ((L.tall ? 0.12 : 0.04)), h * ((L.tall ? 0.03 : 0.05)))
            granulate(c, w, h, 0.12)
        })
        ctx.drawImage(rocks, 0.0, 0.0)
    }
    static func kind_cairn(_ PNT: RPainter2, _ ctx: C2D, _ w: Double, _ h: Double, _ L: Layout, _ pal: Pal, _ S: RScene, _ theme: String, _ t: Double, _ key: String) {
        let base: C2DSurface = PNT.layer("c-base", key, w, h, { (c: C2D) -> Void in
            skyGrad(c, w, h, L.horizon, pal)
            clouds(c, w, h, L.horizon, pal, rng(S.seed), 5.0)
            paintFar(c, w, h, L, pal, rng(S.seed + 1.0), S.seed, S)
        })
        ctx.drawImage(base, 0.0, 0.0)
        let mist: C2DSurface = PNT.layer("c-mist", "\(JS.str(w))x\(JS.str(h)):\(theme):\(JS.str(S.night))", w * 2.0, h, { (c: C2D) -> Void in
            paintMist(c, w * 2.0, h, ([L.horizon, L.ridgeY + h * 0.1] as [Double]), pal, rng(7.0))
        })
        ctx.globalAlpha = JS.min(1.0, S.mist)
        ctx.drawImage(mist, -(JSMath.rem((t * w * 0.006), w)), 0.0)
        ctx.globalAlpha = 1.0
        let near: C2DSurface = PNT.layer("c-near", "\(key):\(JS.toFixed(S.tree, 3.0)):\(JS.str(S.rubble))", w, h, { (c: C2D) -> Void in
            paintLedge(c, w, h, L, pal, rng(S.seed + 2.0), S)
        })
        ctx.drawImage(near, 0.0, 0.0)
        let st: C2DSurface = PNT.layer("c-stones", "\(key):\(JS.toFixed(((S.stones ?? 0.0)), 3.0))", w, h, { (c: C2D) -> Void in
            cairn(c, L, pal, (S.stones ?? 0.0), S.seed * 3.0 + 1.0)
        })
        ctx.drawImage(st, 0.0, 0.0)
    }
    static func kind_hourglass(_ PNT: RPainter2, _ ctx: C2D, _ w: Double, _ h: Double, _ L: Layout, _ pal: Pal, _ S: RScene, _ theme: String, _ t: Double, _ key: String) {
        if ((S.hgBg != nil && S.hgBg! != "hourglass") && S.hgBg! != "ridge") {
            kindDispatch(PNT, S.hgBg!, ctx, w, h, L, pal, S, theme, t, key + ":bg")
            let ledge: C2DSurface = PNT.layer("h-ledge2", key, w, h, { (c: C2D) -> Void in
                paintLedge(c, w, h, Layout(horizon: L.horizon, peakX: L.peakX, peakTop: L.peakTop, peakHalf: L.peakHalf, ridgeY: L.ridgeY, ledgeTop: L.ledgeTop, ledgeX: (L.tall ? w * 0.25 : w * 0.56), rockX: L.rockX, rockW: L.rockW, treeX: L.treeX, treeH: L.treeH, sunX: L.sunX, tall: L.tall), pal, rng(S.seed + 2.0), RScene.make([S]) { _o in _o.tree = 0.0; _o.rubble = 0.0 }, true)
            })
            ctx.drawImage(ledge, 0.0, 0.0)
            let Hb: Double = (L.tall ? h * 0.32 : h * 0.66)
            if S.prop == "lantern" {
                lantern(ctx, (L.tall ? w * 0.55 : L.rockX + w * 0.06), L.ledgeTop + h * 0.012, Hb * 0.8, (S.candle ?? 1.0), t, pal)
            } else if S.prop != "none" {
                hourglass(ctx, (L.tall ? w * 0.55 : L.rockX + w * 0.06), L.ledgeTop + h * 0.012, Hb, (S.sand ?? 1.0), t, pal, theme)
            }
            return
        }
        let base: C2DSurface = PNT.layer("h-base", key, w, h, { (c: C2D) -> Void in
            skyGrad(c, w, h, L.horizon, pal)
            clouds(c, w, h, L.horizon, pal, rng(S.seed), 5.0)
            paintFar(c, w, h, L, pal, rng(S.seed + 1.0), S.seed, S)
        })
        ctx.drawImage(base, 0.0, 0.0)
        let mist: C2DSurface = PNT.layer("h-mist", "\(JS.str(w))x\(JS.str(h)):\(theme):\(JS.str(S.night))", w * 2.0, h, { (c: C2D) -> Void in
            paintMist(c, w * 2.0, h, ([L.horizon, L.ridgeY + h * 0.1] as [Double]), pal, rng(7.0))
        })
        ctx.globalAlpha = JS.min(1.0, S.mist)
        ctx.drawImage(mist, -(JSMath.rem((t * w * 0.006), w)), 0.0)
        ctx.globalAlpha = 1.0
        let near: C2DSurface = PNT.layer("h-near", key, w, h, { (c: C2D) -> Void in
            paintLedge(c, w, h, L, pal, rng(S.seed + 2.0), RScene.make([S]) { _o in _o.tree = 0.0; _o.rubble = 0.0 }, true)
        })
        ctx.drawImage(near, 0.0, 0.0)
        let Hh: Double = (L.tall ? h * 0.32 : h * 0.66)
        if S.prop == "lantern" {
            lantern(ctx, (L.tall ? w * 0.5 : L.rockX + w * 0.03), L.ledgeTop + h * 0.012, Hh * 0.8, (S.candle ?? 1.0), t, pal)
        } else if S.prop != "none" {
            hourglass(ctx, (L.tall ? w * 0.5 : L.rockX + w * 0.03), L.ledgeTop + h * 0.012, Hh, (S.sand ?? 1.0), t, pal, theme)
        }
    }
    static func kindDispatch(_ PNT: RPainter2, _ k: String, _ ctx: C2D, _ w: Double, _ h: Double, _ L: Layout, _ pal: Pal, _ S: RScene, _ theme: String, _ t: Double, _ key: String) {
        switch k {
        case "night":
            kind_night(PNT, ctx, w, h, L, pal, S, theme, t, key)
        case "beach":
            kind_beach(PNT, ctx, w, h, L, pal, S, theme, t, key)
        case "sunrise":
            kind_sunrise(PNT, ctx, w, h, L, pal, S, theme, t, key)
        case "path":
            kind_path(PNT, ctx, w, h, L, pal, S, theme, t, key)
        case "fog":
            kind_fog(PNT, ctx, w, h, L, pal, S, theme, t, key)
        case "lake":
            kind_lake(PNT, ctx, w, h, L, pal, S, theme, t, key)
        case "sunset":
            kind_sunset(PNT, ctx, w, h, L, pal, S, theme, t, key)
        case "cairn":
            kind_cairn(PNT, ctx, w, h, L, pal, S, theme, t, key)
        case "hourglass":
            kind_hourglass(PNT, ctx, w, h, L, pal, S, theme, t, key)
        default: break
        }
    }
}
